const body=$input.first().json.body;
if(!body || typeof body!=='object' || body.website)throw new Error('Invalid contact request');
for(const key of ['name','email','subject','message'])if(typeof body[key]!=='string' || !body[key].trim())throw new Error('Missing contact details');
if(body.message.length>4000 || body.subject.length>200)throw new Error('Message is too long');
// Content-derived retry key, not a security token. Database compares the full payload on reuse.
const seed=JSON.stringify([new Date().toISOString().slice(0,10),body.name,body.email.toLowerCase(),body.subject,body.message]);
const hash=[2166136261,2246822519,3266489917,668265263].map(start=>{let h=start;for(let i=0;i<seed.length;i++){h=Math.imul(h^seed.charCodeAt(i),16777619);}return (h>>>0).toString(16).padStart(8,'0');}).join('');
const requestId=body.requestId || `${hash.slice(0,8)}-${hash.slice(8,12)}-${hash.slice(12,16)}-${hash.slice(16,20)}-${hash.slice(20)}`;
const scrub=value=>String(value).replace(/\b\d{3}-\d{2}-\d{4}\b/g,'[redacted]').replace(/\b(?:\d[ -]*?){13,19}\b/g,'[redacted]').replace(/\b(?:sk-|sb_secret_)[a-zA-Z0-9_-]{16,}\b/g,'[redacted]');
return [{json:{p_payload:{requestId,event:'intro_contact_request',intent:'website-contact',source:'sweetwater-website-contact',contactMethod:'email',contact:{name:body.name.trim(),email:body.email.trim(),phone:null},context:{summary:scrub(body.subject+' — '+body.message).slice(0,1000)},messages:[{role:'user',content:scrub(body.message)}],consent:{marketing:false},testMode:body.testMode===true}}}];
